// partner-click - single-file version (generated by scripts/bundle-functions.js; the readable source is supabase/functions/)
import { createClient, type SupabaseClient } from "npm:@supabase/supabase-js@2";

// ---- shared helpers ----

const env = (k: string, fallback = ""): string => Deno.env.get(k) ?? fallback;

const siteUrl = (): string => env("SITE_URL", "https://www.vertexstealth.top").replace(/\/+$/, "");

/** Origins allowed to call the public functions from a browser. */
function allowedOrigins(): string[] {
  const list = env("ALLOWED_ORIGINS");
  return (list ? list.split(",") : [siteUrl(), "https://vertexstealth.top", "https://www.vertexstealth.top"]).map((s) => s.trim().replace(/\/+$/, "")).filter(Boolean);
}

function corsHeaders(req: Request): Record<string, string> {
  const origin = req.headers.get("origin") ?? "";
  const h: Record<string, string> = {
    "Vary": "Origin",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "content-type, authorization, apikey, x-client-info",
    "Access-Control-Max-Age": "86400",
  };
  if (origin && allowedOrigins().includes(origin)) h["Access-Control-Allow-Origin"] = origin;
  return h;
}

function reply(req: Request, status: number, body: unknown): Response {
  return new Response(status === 204 ? null : JSON.stringify(body), {
    status,
    headers: { ...corsHeaders(req), "Content-Type": "application/json", "Cache-Control": "no-store" },
  });
}

/** Browsers always send Origin on cross-site POSTs; refuse ones from sites we do not list. */
function originAllowed(req: Request): boolean {
  const origin = req.headers.get("origin");
  return !origin || allowedOrigins().includes(origin.replace(/\/+$/, ""));
}

async function readJson(req: Request, maxBytes = 20_000): Promise<Record<string, unknown> | null> {
  const len = Number(req.headers.get("content-length") ?? "0");
  if (len > maxBytes) return null;
  try {
    const text = await req.text();
    if (text.length > maxBytes) return null;
    const v = JSON.parse(text);
    return v && typeof v === "object" && !Array.isArray(v) ? v : null;
  } catch { return null; }
}

const str = (v: unknown, max: number): string => (typeof v === "string" ? v.trim().slice(0, max) : "");

async function sha256Hex(s: string): Promise<string> {
  const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

function randomToken(bytes = 32): string {
  const b = crypto.getRandomValues(new Uint8Array(bytes));
  return btoa(String.fromCharCode(...b)).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", "");
}

function clientIp(req: Request): string {
  return (req.headers.get("cf-connecting-ip") ?? req.headers.get("x-forwarded-for") ?? "").split(",")[0].trim();
}

const esc = (s: string): string =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

function serviceClient(): SupabaseClient {
  return createClient(env("SUPABASE_URL"), env("SUPABASE_SERVICE_ROLE_KEY"), { auth: { persistSession: false, autoRefreshToken: false } });
}

/** A client that runs queries AS the signed-in caller, so Postgres' is_admin() check applies. */
function userClient(authHeader: string): SupabaseClient {
  return createClient(env("SUPABASE_URL"), env("SUPABASE_ANON_KEY"), {
    auth: { persistSession: false, autoRefreshToken: false },
    global: { headers: { Authorization: authHeader } },
  });
}

// ---- partner-click ----
// POST { code }  (public, no JWT) - counts a visit on a partner link and says whether the code exists

async function handle(req: Request): Promise<Response> {
  if (req.method === "OPTIONS") return reply(req, 204, null);
  if (req.method !== "POST") return reply(req, 405, { error: "method_not_allowed" });
  if (!originAllowed(req)) return reply(req, 403, { error: "forbidden_origin" });
  const b = await readJson(req, 1000);
  const code = str(b?.code, 12).toUpperCase();
  if (!/^[A-Z0-9]{8}$/.test(code)) return reply(req, 200, { valid: false });
  const { data, error } = await serviceClient().rpc("partner_record_click", { p_code: code });
  if (error) { console.error("click failed", error.message); return reply(req, 200, { valid: false }); }
  return reply(req, 200, { valid: data === true, code });
}
Deno.serve(handle);